package game.agent.eval;
import game.agent.growth.*;import game.agent.llm.Json;import game.agent.runtime.AgentLoop;import game.agent.tools.ToolRequest;import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class GrowthEvaluationTest {
 @Test void sameSeedResetReproducesIndividualNatureEncountersAndActions(){GrowthWorld a=SeededGrowthFixture.reset(11,"TREECKO"),b=SeededGrowthFixture.reset(11,"TREECKO");assertEquals(Json.write(a.export()),Json.write(b.export()));assertEquals(SeededGrowthFixture.fingerprint(a.export()),SeededGrowthFixture.fingerprint(b.export()));for(int i=0;i<30;i++){String tool=i<1?"go_to_region":i<4?"move_to":i<7?"use_skill":"capture";Map<String,Object> args=tool.equals("go_to_region")?Json.object("regionId","forest"):tool.equals("use_skill")?Json.object("targetId","forest-1-0","moveId","POUND"):Json.object("targetId","forest-1-0");assertEquals(a.execute(tool,args).getCode(),b.execute(tool,args).getCode());assertEquals(Json.write(a.export()),Json.write(b.export()));}GrowthWorld reset=SeededGrowthFixture.reset(11,"TREECKO");assertEquals(0,reset.turn());assertNotEquals(a.turn(),reset.turn());}
 @Test void differentSeedChangesEnvironmentIndividuals(){assertNotEquals(SeededGrowthFixture.fingerprint(SeededGrowthFixture.reset(11,"TREECKO").export()),SeededGrowthFixture.fingerprint(SeededGrowthFixture.reset(12,"TREECKO").export()));}
 @Test void baselineBatchUsesNativeToolsAndKeepsCompleteTrace()throws Exception{List<Map<String,Object>> runs=new ArrayList<>();for(long seed:new long[]{11,22}){Map<String,Object> result=GrowthBatchEvaluation.run(seed,"TREECKO",GrowthBatchEvaluation.scripted(),"scripted","baseline",1000,10000);assertEquals("COMPLETED",result.get("terminal"));Map<String,Object> metrics=Json.asObject(result.get("metrics"));long steps=0;for(Object v:Json.asArray(result.get("trace")))if(Json.asObject(v).get("toolName")!=null)steps++;assertEquals(steps,((Number)metrics.get("actionSteps")).longValue());assertNull(metrics.get("totalTokens"));assertNull(metrics.get("cost"));runs.add(result);}Map<String,Object> batch=GrowthBatchEvaluation.batch(runs,"scripted","baseline");assertEquals(1.0,batch.get("completionRate"));assertEquals(false,batch.get("realAi"));}
 @Test void actualUsageIsCountedOncePerDecisionNotEveryContinuation()throws Exception{AgentLoop.DecisionProvider baseline=GrowthBatchEvaluation.scripted();AgentLoop.DecisionProvider metered=new AgentLoop.DecisionProvider(){public ToolRequest decide(AgentLoop.Context c){return baseline.decide(c);}public Map<String,Number> getUsage(){Map<String,Number> usage=new HashMap<>();usage.put("inputTokens",10L);usage.put("outputTokens",5L);usage.put("totalTokens",15L);return usage;}};Map<String,Object> run=GrowthBatchEvaluation.run(11,"MUDKIP",metered,"mock","mock",1000,10000);Map<String,Object> metrics=Json.asObject(run.get("metrics"));int calls=Json.asArray(run.get("providerCalls")).size();assertTrue(((Number)metrics.get("actionSteps")).longValue()>calls);assertEquals(15L*calls,metrics.get("totalTokens"));assertEquals(true,metrics.get("usageComplete"));assertNull(metrics.get("cost"));}
 @Test void partialUsageNeverBecomesCompleteOrZeroCost(){List<Map<String,Object>> calls=Arrays.asList(Json.object("latencyMs",1,"usage",Json.object("inputTokens",10,"outputTokens",5,"totalTokens",15)),Json.object("latencyMs",2,"usage",Collections.emptyMap()));Map<String,Object> metrics=GrowthBatchEvaluation.metrics(Collections.emptyList(),calls,"FAILED",0);assertEquals(false,metrics.get("usageComplete"));assertNull(metrics.get("totalTokens"));assertEquals(10L,metrics.get("observedInputTokens"));assertNull(metrics.get("cost"));assertNull(metrics.get("recoverySuccessRate"));}
 @Test void duplicateCaseOrEmptyBatchIsRejected()throws Exception{assertThrows(IllegalArgumentException.class,()->GrowthBatchEvaluation.batch(Collections.emptyList(),"scripted","baseline"));Map<String,Object> row=GrowthBatchEvaluation.run(11,"TREECKO",GrowthBatchEvaluation.scripted(),"scripted","baseline",1000,10000);assertThrows(IllegalArgumentException.class,()->GrowthBatchEvaluation.batch(Arrays.asList(row,row),"scripted","baseline"));}
 @Test void failedProviderRemainsFailureWithoutScriptFallback()throws Exception{Map<String,Object> row=GrowthBatchEvaluation.run(11,"TREECKO",c->{throw new game.agent.llm.ProviderException(game.agent.llm.ProviderException.Code.CONFIGURATION);},"mock","unavailable",1000,10000);assertNotEquals("COMPLETED",row.get("terminal"));assertEquals(0,GrowthPokemon.num(Json.asObject(row.get("finalWorld")).get("turn")));assertNull(Json.asObject(row.get("metrics")).get("totalTokens"));}
}
